package ai.allo.car.ui

import ai.allo.car.model.*
import ai.allo.car.gleo.GleoFunctions
import java.io.File
import kotlinx.serialization.json.*
import kotlin.test.*

/** These full snapshots are generated by the phone controller, not a second handwritten car contract. */
class AffinityFishingFixtureTest {
    private fun snapshots(): JsonObject {
        val file = generateSequence(File(requireNotNull(System.getProperty("user.dir")))) { it.parentFile }
            .map { File(it, "data/fixtures/affinity-fishing-v2.json") }.first { it.isFile }
        return Json.parseToJsonElement(file.readText()).jsonObject
    }

    @Test fun `phone lifecycle keeps fishing records and the selected companion on the car`() {
        val reducer = GameSnapshotReducer()
        for ((name, snapshot) in snapshots()) {
            assertTrue(reducer.apply(snapshot.jsonObject, root = true), name)
            val game = reducer.game
            assertTrue(game.invalidBlocks.isEmpty(), name)
            assertEquals("fixture-companion", game.companion?.displayId, name)
            assertEquals("road_sprout", game.companion?.speciesId, name)
            assertEquals(1L, game.fishing?.totalRecords, name)
            assertEquals("paused", game.fishing?.state, name)
            assertEquals("함께 가는 중", PetSummary.from(game,true,SpeciesCatalog.EMPTY).status, name)
            assertEquals(PleosRoute.Paused, PleosFlow.route(true,true,false,true,true,false,game), name)
        }
        assertEquals("failed", reducer.game.stage)
        assertEquals(0.0,reducer.game.affinity?.score)
    }

    @Test fun `phone pending result is not a hatch until the persisted snapshot arrives`() {
        val fixture=snapshots()
        val pending=GameSnapshotReader.parse(fixture["resultPending"]!!.jsonObject)!!
        assertEquals("incubating",pending.stage)
        assertTrue(FeatureStatus.from(pending,SpeciesCatalog.EMPTY).affinity!!.contains("저장 중"))
        assertEquals("fail",GleoFunctions.respond(GleoFunctions.CELEBRATE_HATCH,pending).status)
        val hatched=GameSnapshotReader.parse(fixture["hatched"]!!.jsonObject)!!
        assertEquals("hatched",hatched.stage)
        assertTrue(FeatureStatus.from(hatched,SpeciesCatalog.EMPTY).affinity!!.contains("부화 완료"))
        assertEquals("success",GleoFunctions.respond(GleoFunctions.CELEBRATE_HATCH,hatched).status)
        assertNotEquals(hatched.speciesId,hatched.companion?.speciesId)
        val next=GameSnapshotReader.parse(fixture["nextEgg"]!!.jsonObject)!!
        assertEquals("incubating",next.stage)
        assertEquals(0.0,next.affinity?.score)
        assertEquals(hatched.fishing,next.fishing)
        assertEquals(hatched.companion,next.companion)
    }
}
